//! Charge generated bytes as they are produced without first allocating large formatted results.

use std::fmt::{self, Write};

use super::ScriptError;

pub(crate) struct Text {
    text: String,
    limit: usize,
}

impl Text {
    pub fn new(limit: usize) -> Self {
        Self {
            text: String::new(),
            limit,
        }
    }
    pub fn add(&mut self, text: &str) -> Result<(), ScriptError> {
        self.write_str(text).map_err(|_| ScriptError::limit())
    }
    pub fn format(&mut self, args: fmt::Arguments<'_>) -> Result<(), ScriptError> {
        self.write_fmt(args).map_err(|_| ScriptError::limit())
    }
    pub fn quoted(&mut self, name: &str) -> Result<(), ScriptError> {
        // The relation key is not just a GraphQL Name.
        self.add("\"")?;
        for ch in name.chars() {
            match ch {
                '"' => self.add("\\\"")?,
                '\\' => self.add("\\\\")?,
                '\0'..='\u{1f}' | '\u{7f}' => self.format(format_args!("\\{:03}", ch as u32))?,
                _ => self.add(ch.encode_utf8(&mut [0; 4]))?,
            }
        }
        self.add("\"")
    }
    pub fn key(&mut self, name: &str) -> Result<(), ScriptError> {
        self.add("  [")?;
        self.quoted(name)?;
        self.add("]: ")
    }
    pub fn finish(self) -> String {
        self.text
    }
}

impl Write for Text {
    fn write_str(&mut self, value: &str) -> fmt::Result {
        if value.len() > self.limit.saturating_sub(self.text.len()) {
            return Err(fmt::Error);
        }
        self.text.push_str(value);
        Ok(())
    }
}
